import React from "react";
import Slider from "react-slick";
import { Box } from "@mui/material";
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";
import "../Css/carouselStyles.css";

const BannerCarousel = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 3000,
    arrows: true,
  };

  return (
    <Box sx={{ maxWidth: "100%", overflow: "hidden", position: "relative" }}>
      <Slider {...settings}>
        <Box>
          <a href="https://www.techcareer.net/courses">
            <img
              src="./assets/images/banner1.webp"
              alt="Banner 1"
              style={{
                width: "100%",
                height: "435px",
                objectFit: "cover",
              }}
            />
          </a>
        </Box>
        <Box>
          <a href="https://www.techcareer.net/jobs">
            <img
              src="./assets/images/banner2.webp"
              alt="Banner 2"
              style={{
                width: "100%",
                height: "435px",
                objectFit: "cover",
              }}
            />
          </a>
        </Box>
        <Box>
          <a href="https://www.techcareer.net/blog">
            <img
              src="./assets/images/banner3.webp"
              alt="Banner 3"
              style={{
                width: "100%",
                height: "435px",
                objectFit: "cover",
              }}
            />
          </a>
        </Box>
      </Slider>
    </Box>
  );
};

export default BannerCarousel;
